import * as THREE from 'three';
export class Wake{
 constructor(scene,mobile){this.count=mobile?650:1400;this.index=0;this.life=new Float32Array(this.count);this.velocity=new Float32Array(this.count*3);this.positions=new Float32Array(this.count*3);this.sizes=new Float32Array(this.count);this.alphas=new Float32Array(this.count);this.baseSize=new Float32Array(this.count);const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(this.positions,3));g.setAttribute('size',new THREE.BufferAttribute(this.sizes,1));g.setAttribute('alpha',new THREE.BufferAttribute(this.alphas,1));this.geometry=g;
 const m=new THREE.ShaderMaterial({transparent:true,depthWrite:false,blending:THREE.NormalBlending,uniforms:{color:{value:new THREE.Color('#9db9b7')}},vertexShader:'attribute float size;attribute float alpha;varying float a;void main(){a=alpha;vec4 p=modelViewMatrix*vec4(position,1.);gl_PointSize=clamp(size*420./max(1.,-p.z),1.,24.);gl_Position=projectionMatrix*p;}',fragmentShader:'uniform vec3 color;varying float a;void main(){float d=length(gl_PointCoord-.5)*2.;if(d>1.)discard;float foam=(1.-smoothstep(.15,1.,d));gl_FragColor=vec4(color,a*foam);}',toneMapped:false});this.mesh=new THREE.Points(g,m);this.mesh.frustumCulled=false;this.mesh.layers.set(1);scene.add(this.mesh);}
 emit(x,z,heading,speed,size=1){const n=this.index++%this.count,i=n*3,side=Math.random()>.5?1:-1,rx=Math.cos(heading),rz=-Math.sin(heading);this.positions[i]=x+rx*side*(1+Math.random());this.positions[i+1]=.18+Math.random()*.25;this.positions[i+2]=z+rz*side*(1+Math.random());this.velocity[i]=rx*side*(1.5+Math.random()*2)+Math.sin(heading)*speed*.05;this.velocity[i+1]=Math.random()*(speed>25?2:.3);this.velocity[i+2]=rz*side*(1.5+Math.random()*2)+Math.cos(heading)*speed*.05;this.life[n]=1.8+Math.random();this.baseSize[n]=size*.58;}
 update(dt){for(let n=0;n<this.count;n++){if(this.life[n]<=0){this.alphas[n]=0;continue;}this.life[n]-=dt;const i=n*3;this.positions[i]+=this.velocity[i]*dt;this.positions[i+2]+=this.velocity[i+2]*dt;this.positions[i+1]=Math.max(.14,this.positions[i+1]+this.velocity[i+1]*dt);this.velocity[i+1]-=dt*3;this.sizes[n]=this.baseSize[n]*(3.3-this.life[n])*.8;this.alphas[n]=Math.min(.18,this.life[n]*.1);}for(const a of Object.values(this.geometry.attributes))a.needsUpdate=true;}
 clear(){this.life.fill(0);this.alphas.fill(0);}
}

// Persistent water-level foam strips. Unlike spray sprites, these follow each hull's
// travelled path and stay flat on the river when the camera turns.
export class SurfaceWakes{
 constructor(scene,capacity=48){this.trails=new Map();this.max=capacity*40*18;this.positions=new Float32Array(this.max*3);this.uv=new Float32Array(this.max*2);this.alpha=new Float32Array(this.max);const g=this.geometry=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(this.positions,3));g.setAttribute('uv',new THREE.BufferAttribute(this.uv,2));g.setAttribute('aFade',new THREE.BufferAttribute(this.alpha,1));g.setDrawRange(0,0);
 const m=this.material=new THREE.ShaderMaterial({transparent:true,depthWrite:false,side:THREE.DoubleSide,uniforms:{time:{value:0}},vertexShader:'attribute float aFade;varying float fade;varying vec2 vUv;varying vec2 riverPoint;void main(){fade=aFade;vUv=uv;riverPoint=position.xz;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:`varying float fade;varying vec2 vUv;varying vec2 riverPoint;uniform float time;
 float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
 float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);}
 // Interpolated UVs and GPU sine approximations can stray just outside [0,1].
 // A negative fractional-power base creates NaNs that bloom spreads over the view.
 void main(){float edge=pow(max(0.,sin(clamp(vUv.x,0.,1.)*3.14159)),.75);vec2 p=riverPoint*2.4+vec2(time*.12,-time*.08);float n=noise(p)*.65+noise(p*3.1)*.35;
 float foam=smoothstep(.24,.70,n)*(.6+.4*noise(p*.4));gl_FragColor=vec4(vec3(.33,.41,.40),foam*edge*fade);
 #include <tonemapping_fragment>
 #include <colorspace_fragment>
 }`});this.mesh=new THREE.Mesh(g,m);this.mesh.frustumCulled=false;this.mesh.layers.set(1);scene.add(this.mesh);this.clock=0;this.geometryAge=0;for(const a of Object.values(g.attributes))a.setUsage(THREE.DynamicDrawUsage);}
 clear(){this.trails.clear();this.geometry.setDrawRange(0,0);}
 update(dt,actors){this.material.uniforms.time.value+=dt;this.geometryAge+=dt;if(this.geometryAge<1/30)return;dt=this.geometryAge;this.geometryAge=0;this.clock+=dt;const emit=this.clock>.07;if(emit)this.clock=0;let vertex=0;
  const write=(x,z,u,v,a)=>{if(vertex>=this.max)return;const i=vertex*3;this.positions[i]=x;this.positions[i+1]=.15+Math.sin(x*.47+z*.28+this.material.uniforms.time.value*1.1)*.095+Math.sin(z*.73-x*.22-this.material.uniforms.time.value*1.42)*.038;this.positions[i+2]=z;this.uv[vertex*2]=u;this.uv[vertex*2+1]=v;this.alpha[vertex]=a;vertex++;};
  for(const trail of this.trails.values()){for(const p of trail)p.age+=dt;while(trail.length&&trail.at(-1).age>2.4)trail.pop();}
  for(const actor of actors){let trail=this.trails.get(actor);if(!trail){trail=[];this.trails.set(actor,trail);}const speed=Math.hypot(actor.vx,actor.vz);if(emit&&speed>2){trail.unshift({x:actor.x+Math.sin(actor.heading)*(actor.length||12)*.45,z:actor.z+Math.cos(actor.heading)*(actor.length||12)*.45,heading:actor.heading,age:0,width:actor.width||2.35,speed});if(trail.length>39)trail.pop();}
   for(let i=1;i<trail.length;i++){const a=trail[i-1],b=trail[i];for(const side of[-1,0,1]){const edge=p=>{const spread=p.width*.35+p.age*(1.8+p.speed*.035),thickness=.35+p.age*(.8+p.width*.12),rx=Math.cos(p.heading)*(side||1),rz=-Math.sin(p.heading)*(side||1);if(side===0){const half=p.width*.18+p.age*.38;return[{x:p.x-rx*half,z:p.z-rz*half},{x:p.x+rx*half,z:p.z+rz*half}];}return[{x:p.x+rx*spread,z:p.z+rz*spread},{x:p.x+rx*(spread+thickness),z:p.z+rz*(spread+thickness)}];};const aa=edge(a),bb=edge(b),alpha=p=>Math.max(0,1-p.age/2.4)*Math.min(1,p.age*12)*(side===0?.60:.74);for(const [p,u,v,fade]of [[aa[0],0,i-1,alpha(a)],[aa[1],1,i-1,alpha(a)],[bb[0],0,i,alpha(b)],[aa[1],1,i-1,alpha(a)],[bb[1],1,i,alpha(b)],[bb[0],0,i,alpha(b)]])write(p.x,p.z,u,v*.07,fade);}}
  }this.geometry.setDrawRange(0,vertex);for(const a of Object.values(this.geometry.attributes)){a.clearUpdateRanges();a.addUpdateRange(0,vertex*a.itemSize);a.needsUpdate=true;}
 }
}
